export const NOTORGANIC_DEFAULT_ISSUER = "https://api.notorganic.info";
export const NOTORGANIC_PRODUCT = "twyne";
export const NOTORGANIC_ASSERTION_TTL_SECONDS = 60;
export const NOTORGANIC_GENERATION_ID_HEADER = "x-twyne-generation-request-id";

export function notOrganicGenerationRequestHeaders(
  headers?: Readonly<Record<string, string | undefined>>,
): Record<string, string | undefined> {
  return { ...headers, [NOTORGANIC_GENERATION_ID_HEADER]: crypto.randomUUID() };
}

/** No implicit spending allowance: deployment must supply an approved limit. */
export function notOrganicGenerationBudgetMicrousd(value: unknown): number {
  const number =
    typeof value === "string" && /^[1-9]\d*$/.test(value)
      ? Number(value)
      : value;
  if (
    typeof number !== "number" ||
    !Number.isSafeInteger(number) ||
    number <= 0
  ) {
    throw new Error(
      "An explicit positive safe-integer Not Organic generation budget in micro-USD is required.",
    );
  }
  return number;
}

function tokenBudgetCeiling(accessToken: string): number | undefined {
  const parts = accessToken.split(".");
  if (parts.length !== 3) return undefined;
  try {
    const payload = JSON.parse(
      atob(parts[1]!.replace(/-/g, "+").replace(/_/g, "/")),
    ) as { max_cost_microusd?: unknown };
    if (typeof payload.max_cost_microusd !== "number") {
      throw new Error("Invalid token budget type");
    }
    return notOrganicGenerationBudgetMicrousd(
      payload.max_cost_microusd ?? null,
    );
  } catch {
    throw new Error(
      "The issued Not Organic token has no valid request-budget ceiling.",
    );
  }
}

export const NOTORGANIC_MODEL_ALIASES = [
  "fast",
  "balanced",
  "reasoning",
  "vision",
  "embedding",
  "image",
  "audio",
  "speech-eleven-v4",
  "realtime",
] as const;
export type NotOrganicModelAlias = (typeof NOTORGANIC_MODEL_ALIASES)[number];

// Existing Not Organic gateway ADMIN_CAPS_MICROUSD contract, verified against
// the running gateway. These can only tighten Twyne's approved outer ceiling.
const NOTORGANIC_ALIAS_CEILINGS_MICROUSD: Record<NotOrganicModelAlias, number> =
  {
    fast: 250_000,
    balanced: 500_000,
    reasoning: 2_000_000,
    vision: 1_000_000,
    embedding: 100_000,
    image: 2_000_000,
    audio: 1_000_000,
    "speech-eleven-v4": 1_000_000,
    realtime: 2_000_000,
  };

export interface ProductAssertionInput {
  readonly did: string;
  readonly feature: string;
  readonly capabilities: readonly string[];
  readonly sessionVersion?: number;
}

export interface NotOrganicAccessToken {
  readonly accessToken: string;
  readonly expiresIn?: number;
  readonly tokenType?: string;
  readonly dpop: DpopKeyPair;
}

export interface DpopKeyPair {
  readonly privateKey: CryptoKey;
  readonly publicJwk: JsonWebKey;
}

export interface NotOrganicOpenAiRoute {
  readonly baseURL: string;
  readonly apiKey: string;
  readonly model: NotOrganicModelAlias;
  readonly headers: Readonly<Record<string, string>>;
  readonly fetch: typeof fetch;
}

export interface DidLinkRecord {
  readonly did: string;
  readonly productSubject: string;
}

function base64url(input: string | Uint8Array): string {
  const bytes =
    typeof input === "string" ? new TextEncoder().encode(input) : input;
  let binary = "";
  for (const byte of bytes) binary += String.fromCharCode(byte);
  return btoa(binary).replace(/=/g, "").replace(/\+/g, "-").replace(/\//g, "_");
}

function decodeBase64(value: string): Uint8Array {
  const binary = atob(value.replace(/\s/g, ""));
  return Uint8Array.from(binary, (character) => character.charCodeAt(0));
}

async function loadPrivateKey(value: string): Promise<CryptoKey> {
  const trimmed = value.trim();
  if (trimmed.startsWith("{")) {
    return crypto.subtle.importKey(
      "jwk",
      JSON.parse(trimmed),
      { name: "Ed25519" },
      false,
      ["sign"],
    );
  }
  const encoded = trimmed.includes("BEGIN PRIVATE KEY")
    ? trimmed
        .replace("-----BEGIN PRIVATE KEY-----", "")
        .replace("-----END PRIVATE KEY-----", "")
    : trimmed;
  return crypto.subtle.importKey(
    "pkcs8",
    decodeBase64(encoded),
    { name: "Ed25519" },
    false,
    ["sign"],
  );
}

export function notOrganicEnabled(
  env: Readonly<Record<string, string | undefined>> = process.env,
): boolean {
  const value = env.NOTORGANIC_ENABLED?.trim().toLowerCase();
  return value === "1" || value === "true";
}

export function notOrganicIssuer(
  env: Readonly<Record<string, string | undefined>> = process.env,
): string {
  return (env.NOTORGANIC_ISSUER ?? NOTORGANIC_DEFAULT_ISSUER).replace(
    /\/$/,
    "",
  );
}

export function notOrganicOpenAiRoute(
  token: NotOrganicAccessToken,
  alias: NotOrganicModelAlias,
  feature: string,
  issuer = NOTORGANIC_DEFAULT_ISSUER,
  fetchImpl: typeof fetch = fetch,
  options: { readonly maxCostMicrousd?: number } = {},
): NotOrganicOpenAiRoute {
  if (!token.accessToken)
    throw new Error("A provider access token is required");
  if (!feature.trim()) throw new Error("A feature is required");
  const configuredBudget = notOrganicGenerationBudgetMicrousd(
    options.maxCostMicrousd ??
      process.env.NOTORGANIC_GENERATION_MAX_COST_MICROUSD,
  );
  // A token claim can only tighten the approved application limit. The gateway
  // independently verifies the token and still enforces its own alias caps.
  const ceiling = tokenBudgetCeiling(token.accessToken);
  const maxCostMicrousd = Math.min(
    configuredBudget,
    ceiling ?? configuredBudget,
    NOTORGANIC_ALIAS_CEILINGS_MICROUSD[alias],
  );
  return {
    baseURL: `${issuer.replace(/\/$/, "")}/v1`,
    apiKey: token.accessToken,
    model: alias,
    headers: {
      "x-notorganic-product": NOTORGANIC_PRODUCT,
      "x-notorganic-feature": feature,
    },
    fetch: createMeteredDpopFetch(token, maxCostMicrousd, fetchImpl),
  };
}

function createMeteredDpopFetch(
  token: NotOrganicAccessToken,
  maxCostMicrousd: number,
  fetchImpl: typeof fetch,
): typeof fetch {
  const fallbackGenerationId = crypto.randomUUID();
  const authenticatedFetch = createDpopFetch(token, fetchImpl);
  return (async (input: RequestInfo | URL, init?: RequestInit) => {
    const request = new Request(input, init);
    request.signal.throwIfAborted();
    const headers = new Headers(request.headers);
    const generationId =
      headers.get(NOTORGANIC_GENERATION_ID_HEADER) ?? fallbackGenerationId;
    if (!/^[A-Za-z0-9_-]{1,128}$/.test(generationId)) {
      throw new Error("Invalid logical generation request identifier.");
    }
    // SDK retries retain this ID and body. Tool steps change the body; separate
    // generateText invocations receive distinct IDs even with identical prompts.
    const prefix = new TextEncoder().encode(
      JSON.stringify([
        generationId,
        request.method,
        request.url,
        maxCostMicrousd,
      ]),
    );
    const body = new Uint8Array(await request.clone().arrayBuffer());
    const bytes = new Uint8Array(prefix.length + body.length);
    bytes.set(prefix);
    bytes.set(body, prefix.length);
    const digest = new Uint8Array(await crypto.subtle.digest("SHA-256", bytes));
    const key = Array.from(digest, (byte) =>
      byte.toString(16).padStart(2, "0"),
    ).join("");
    headers.delete(NOTORGANIC_GENERATION_ID_HEADER);
    headers.set("idempotency-key", `twyne_${key}`);
    headers.set("x-notorganic-max-cost-microusd", String(maxCostMicrousd));
    request.signal.throwIfAborted();
    return authenticatedFetch(new Request(request, { headers }));
  }) as typeof fetch;
}

export async function createDpopKeyPair(): Promise<DpopKeyPair> {
  const pair = await crypto.subtle.generateKey(
    { name: "ECDSA", namedCurve: "P-256" },
    true,
    ["sign", "verify"],
  );
  return {
    privateKey: pair.privateKey,
    publicJwk: await crypto.subtle.exportKey("jwk", pair.publicKey),
  };
}

async function accessTokenHash(accessToken: string): Promise<string> {
  const digest = await crypto.subtle.digest(
    "SHA-256",
    new TextEncoder().encode(accessToken),
  );
  return base64url(new Uint8Array(digest));
}

export async function createDpopProof(
  token: NotOrganicAccessToken,
  url: string,
  method: string,
  nowSeconds = Math.floor(Date.now() / 1_000),
): Promise<string> {
  const header = {
    alg: "ES256",
    typ: "dpop+jwt",
    jwk: token.dpop.publicJwk,
  };
  const claims = {
    htm: method.toUpperCase(),
    htu: url,
    ath: await accessTokenHash(token.accessToken),
    iat: nowSeconds,
    exp: nowSeconds + 60,
    jti: crypto.randomUUID(),
  };
  const signingInput = `${base64url(JSON.stringify(header))}.${base64url(
    JSON.stringify(claims),
  )}`;
  const signature = await crypto.subtle.sign(
    { name: "ECDSA", hash: "SHA-256" },
    token.dpop.privateKey,
    new TextEncoder().encode(signingInput),
  );
  return `${signingInput}.${base64url(new Uint8Array(signature))}`;
}

export function createDpopFetch(
  token: NotOrganicAccessToken,
  fetchImpl: typeof fetch = fetch,
): typeof fetch {
  return (async (input: RequestInfo | URL, init?: RequestInit) => {
    const request = new Request(input, init);
    const headers = new Headers(request.headers);
    headers.set("authorization", `DPoP ${token.accessToken}`);
    headers.set(
      "dpop",
      await createDpopProof(token, request.url, request.method),
    );
    request.signal.throwIfAborted();
    return fetchImpl(new Request(request, { headers }));
  }) as typeof fetch;
}

/**
 * Sign the 60-second product assertion exchanged for a provider access token.
 * The Ed25519 private key is accepted as PKCS#8 PEM/base64 or a private JWK and
 * never leaves the Convex server action runtime.
 */
export async function signProductAssertion(
  input: ProductAssertionInput,
  privateKey: string,
  options: {
    readonly issuer?: string;
    readonly audience?: string;
    readonly keyId?: string;
    readonly nowSeconds?: number;
    readonly jti?: string;
  } = {},
): Promise<string> {
  if (!input.did.startsWith("did:")) throw new Error("A valid DID is required");
  if (!input.feature.trim()) throw new Error("A feature is required");
  if (input.capabilities.length === 0) {
    throw new Error("At least one capability is required");
  }

  const iat = options.nowSeconds ?? Math.floor(Date.now() / 1_000);
  const header = {
    alg: "EdDSA",
    typ: "JWT",
    ...(options.keyId ? { kid: options.keyId } : {}),
  };
  const claims = {
    typ: "notorganic/assertion+jwt",
    iss: NOTORGANIC_PRODUCT,
    sub: input.did,
    aud: options.audience ?? options.issuer ?? NOTORGANIC_DEFAULT_ISSUER,
    jti: options.jti ?? crypto.randomUUID(),
    iat,
    exp: iat + NOTORGANIC_ASSERTION_TTL_SECONDS,
    session_version: input.sessionVersion ?? 1,
    capabilities: [...input.capabilities],
    feature: input.feature,
    environment: "server",
  };
  const signingInput = `${base64url(JSON.stringify(header))}.${base64url(
    JSON.stringify(claims),
  )}`;
  const signature = await crypto.subtle.sign(
    "Ed25519",
    await loadPrivateKey(privateKey),
    new TextEncoder().encode(signingInput),
  );
  return `${signingInput}.${base64url(new Uint8Array(signature))}`;
}

export async function exchangeProductAssertion(
  assertion: string,
  options: {
    readonly issuer?: string;
    readonly fetch?: typeof fetch;
    readonly dpop?: DpopKeyPair;
  } = {},
): Promise<NotOrganicAccessToken> {
  const issuer = (options.issuer ?? NOTORGANIC_DEFAULT_ISSUER).replace(
    /\/$/,
    "",
  );
  const dpop = options.dpop ?? (await createDpopKeyPair());
  const response = await (options.fetch ?? fetch)(
    `${issuer}/v1/auth/token/exchange`,
    {
      method: "POST",
      headers: { "content-type": "application/json" },
      body: JSON.stringify({
        assertion,
        dpop_jwk: dpop.publicJwk,
      }),
    },
  );
  if (!response.ok) {
    const detail = await response.text().catch(() => "");
    throw new Error(
      `Not Organic token exchange failed (${response.status}): ${detail.slice(0, 300)}`,
    );
  }
  const body = (await response.json()) as {
    access_token?: unknown;
    expires_in?: unknown;
    token_type?: unknown;
  };
  if (typeof body.access_token !== "string" || !body.access_token) {
    throw new Error("Not Organic token exchange returned no access_token");
  }
  return {
    accessToken: body.access_token,
    expiresIn:
      typeof body.expires_in === "number" ? body.expires_in : undefined,
    tokenType:
      typeof body.token_type === "string" ? body.token_type : undefined,
    dpop,
  };
}

export async function issueNotOrganicAccessToken(
  input: ProductAssertionInput,
  env: Readonly<Record<string, string | undefined>> = process.env,
  fetchImpl: typeof fetch = fetch,
): Promise<NotOrganicAccessToken> {
  if (!notOrganicEnabled(env)) {
    throw new Error("Not Organic provider is disabled");
  }
  const privateKey = env.NOTORGANIC_ASSERTION_PRIVATE_KEY;
  if (!privateKey) {
    throw new Error("NOTORGANIC_ASSERTION_PRIVATE_KEY is not configured");
  }
  const issuer = notOrganicIssuer(env);
  const assertion = await signProductAssertion(input, privateKey, {
    issuer,
    audience: env.NOTORGANIC_AUDIENCE ?? "notorganic",
    keyId: env.NOTORGANIC_ASSERTION_KEY_ID,
  });
  return exchangeProductAssertion(assertion, {
    issuer,
    fetch: fetchImpl,
  });
}

/**
 * Pure uniqueness guard used inside the transactional Convex link mutation.
 */
export function assertUniqueDidLink(
  requested: DidLinkRecord,
  existingByDid: DidLinkRecord | null,
  existingBySubject: DidLinkRecord | null,
): void {
  if (
    existingByDid &&
    existingByDid.productSubject !== requested.productSubject
  ) {
    throw new Error("This DID is already linked to another Twyne account");
  }
  if (existingBySubject && existingBySubject.did !== requested.did) {
    throw new Error("This Twyne account is already linked to another DID");
  }
}

export async function providerJsonRequest<T>(
  path: string,
  token: NotOrganicAccessToken,
  init: RequestInit = {},
  options: {
    readonly issuer?: string;
    readonly feature: string;
    readonly fetch?: typeof fetch;
  },
): Promise<T> {
  const issuer = (options.issuer ?? NOTORGANIC_DEFAULT_ISSUER).replace(
    /\/$/,
    "",
  );
  const headers = new Headers(init.headers);
  headers.set("content-type", "application/json");
  headers.set("x-notorganic-product", NOTORGANIC_PRODUCT);
  headers.set("x-notorganic-feature", options.feature);
  const response = await createDpopFetch(token, options.fetch ?? fetch)(
    `${issuer}${path}`,
    {
      ...init,
      headers,
    },
  );
  if (!response.ok) {
    const detail = await response.text().catch(() => "");
    throw new Error(
      `Not Organic API failed (${response.status}): ${detail.slice(0, 300)}`,
    );
  }
  return (await response.json()) as T;
}
/**
 * Pro entitlement — read from the writer's Not Organic wallet.
 *
 * Twyne no longer keeps its own subscription table: the plan lives on the
 * Not Organic account linked at sign-in (`providerIdentities`). Any failure
 * to reach the wallet resolves to "not Pro" so free-tier limits still apply.
 */
import { makeFunctionReference } from "convex/server";
import { hasCurrentTwynePlan } from "../../src/utils/subscription-plan";
import {
  issueNotOrganicAccessToken,
  notOrganicIssuer,
  providerJsonRequest,
} from "./notorganic";

type RunQueryCtx = {
  runQuery: (ref: any, args: any) => Promise<any>;
};

const getLinkedDidBySubject = makeFunctionReference<
  "query",
  { productSubject: string },
  { did: string; sessionVersion: number } | null
>("providerIdentity:getLinkedDidBySubject");

/** Whether the signed-in Twyne user (by Better Auth subject) holds Pro. */
export async function userIsPro(
  ctx: RunQueryCtx,
  productSubject: string,
): Promise<boolean> {
  try {
    const link = await ctx.runQuery(getLinkedDidBySubject, { productSubject });
    if (!link) return false;
    const token = await issueNotOrganicAccessToken({
      did: link.did,
      feature: "wallet",
      capabilities: ["wallet:read"],
      sessionVersion: link.sessionVersion,
    });
    const wallet = await providerJsonRequest<unknown>(
      "/v1/wallet",
      token,
      {},
      { issuer: notOrganicIssuer(), feature: "wallet" },
    );
    return hasCurrentTwynePlan(wallet);
  } catch {
    return false;
  }
}
import type { AuthConfig } from "convex/server";
import { getAuthConfigProvider } from "@convex-dev/better-auth/auth-config";

export default {
  providers: [getAuthConfigProvider()],
} satisfies AuthConfig;

/**
 * Clairic — typed values read out of text.
 *
 * Jev answers questions whose options we wrote down; Clairic reads values we
 * did not enumerate: spans of the state, numbers, dates, durations, lists, and
 * estimates or forecasts with an 80% interval (p10–p90). One parallel forward
 * pass, no generated text, so a `text` answer is always a substring of the
 * state it was given.
 *
 * Every scalar answer carries `p_null`, the probability the value is not in
 * the input. Past `null_threshold` (default 0.5) `value` is null, but `guess`
 * still holds the closest candidate — the near miss is data, not an error.
 *
 * Transport-free, like `system-one.ts`: `convex/extraction.ts` holds the
 * credentials and talks to Not Organic's `POST /v1/extraction`.
 */

export type ExtractionFieldType =
  | "text"
  | "number"
  | "date"
  | "time"
  | "datetime"
  | "duration"
  | "list"
  | "estimate"
  | "forecast";

export type DurationUnit =
  | "seconds"
  | "minutes"
  | "hours"
  | "days"
  | "weeks"
  | "months"
  | "years";

export type ForecastInterval =
  | "step"
  | "minute"
  | "hour"
  | "day"
  | "week"
  | "month"
  | "quarter"
  | "year";

export interface ExtractionField {
  type: ExtractionFieldType;
  instructions?: string;
  unit?: string;
  integer?: boolean;
  decimals?: number;
  items?: "text" | "number" | "date";
  min?: number | string;
  max?: number | string;
  step?: number | "month" | "year";
  scale?: "linear" | "log";
  null_threshold?: number;
  horizon?: number;
  interval?: ForecastInterval;
}

export interface ExtractionRequest {
  state?: string;
  fields: Record<string, ExtractionField>;
  /** ISO date anchoring relative dates and dates written without a year. */
  reference_date?: string;
  options?: { include_quantiles?: boolean; return_state_text?: boolean };
}

export interface ExtractionAnswer {
  type: ExtractionFieldType;
  value: unknown;
  guess?: unknown;
  p_null?: number;
  confidence?: number;
  unit?: string;
  /** `text` answers: [start, end) into the state. */
  span?: [number, number];
  /** `list` answers: one span per item, in input order. */
  spans?: [number, number][];
  mean?: unknown;
  median?: unknown;
  p10?: unknown;
  p90?: unknown;
  p_below?: number;
  p_above?: number;
  quantiles?: unknown[];
  steps?: unknown[];
}

export interface ExtractionUsage {
  input_tokens: number;
  output_tokens: number;
  passes?: number;
}

export interface ExtractionResult {
  ok: boolean;
  model?: string;
  answers?: Record<string, ExtractionAnswer>;
  truncated?: boolean;
  usage?: ExtractionUsage;
  transport?: "notorganic" | "direct" | "none";
  error?: string;
  latencyMs?: number;
}

/** Input tokens only, at the published Workers AI rate. */
export const USD_PER_INPUT_TOKEN = 0.1 / 1_000_000;

/* ── Builders ──────────────────────────────────────────────────── */

export const text = (instructions?: string): ExtractionField => ({
  type: "text",
  ...(instructions ? { instructions } : {}),
});

export const list = (
  items: "text" | "number" | "date",
  instructions?: string,
): ExtractionField => ({
  type: "list",
  items,
  ...(instructions ? { instructions } : {}),
});

export function estimate(
  instructions: string,
  range: { min: number; max: number; unit?: string; step?: number; log?: boolean },
): ExtractionField {
  return {
    type: "estimate",
    instructions,
    min: range.min,
    max: range.max,
    ...(range.unit ? { unit: range.unit } : {}),
    ...(range.step ? { step: range.step } : {}),
    ...(range.log ? { scale: "log" as const } : {}),
  };
}

export function forecast(
  instructions: string,
  range: {
    min: number;
    max: number;
    horizon: number;
    interval: ForecastInterval;
    log?: boolean;
  },
): ExtractionField {
  return {
    type: "forecast",
    instructions,
    min: range.min,
    max: range.max,
    horizon: range.horizon,
    interval: range.interval,
    ...(range.log ? { scale: "log" as const } : {}),
  };
}

/* ── Reading answers ───────────────────────────────────────────── */

/** The exact substring a `text` answer points at, or null. */
export function spanText(
  state: string,
  answer: ExtractionAnswer | undefined,
): string | null {
  const span = answer?.span;
  if (!span || answer?.value === null) return null;
  return state.slice(span[0], span[1]);
}

/** Every substring a `list` answer points at, in input order. */
export function spanTexts(
  state: string,
  answer: ExtractionAnswer | undefined,
): string[] {
  return (answer?.spans ?? []).map(([s, e]) => state.slice(s, e));
}

/**
 * The closest candidate when the value is judged absent: `value` is null but
 * `guess` is not. For text answers the guess is still a span of the state.
 */
export function nearMiss(
  answer: ExtractionAnswer | undefined,
): { guess: unknown; pNull: number } | null {
  if (!answer || answer.value !== null || answer.guess == null) return null;
  return { guess: answer.guess, pNull: answer.p_null ?? 1 };
}

export interface Interval {
  median: number;
  p10: number;
  p90: number;
}

/** The numeric 80% interval of an estimate, or null for date estimates and gaps. */
export function interval(answer: ExtractionAnswer | undefined): Interval | null {
  const { median, p10, p90 } = answer ?? {};
  return typeof median === "number" &&
    typeof p10 === "number" &&
    typeof p90 === "number"
    ? { median, p10, p90 }
    : null;
}

/** One interval per forecast step. */
export function forecastSteps(answer: ExtractionAnswer | undefined): Interval[] {
  if (!answer) return [];
  if (Array.isArray(answer.steps))
    return answer.steps
      .map((s) => interval(s as ExtractionAnswer))
      .filter((s): s is Interval => s !== null);
  const { median, p10, p90 } = answer;
  if (Array.isArray(median) && Array.isArray(p10) && Array.isArray(p90))
    return median.map((m, i) => ({
      median: m as number,
      p10: p10[i] as number,
      p90: p90[i] as number,
    }));
  const single = interval(answer);
  return single ? [single] : [];
}
/**
 * One door for every Clairic extraction Twyne asks for, as `judgement-client`
 * is for Jev. Always through the Convex action: the provider credential lives
 * on the server, and Not Organic meters the spend.
 */
import type { ConvexClient } from "convex/browser";
import { api } from "../../convex/_generated/api";
import type { ExtractionRequest, ExtractionResult } from "./extraction";

export async function askExtraction(
  client: ConvexClient | null | undefined,
  request: ExtractionRequest,
): Promise<ExtractionResult> {
  if (!client) return { ok: false, transport: "none", error: "signed out" };
  const started = performance.now();
  try {
    const result = (await client.action(
      api.extraction.extract,
      request,
    )) as ExtractionResult;
    return { ...result, latencyMs: Math.round(performance.now() - started) };
  } catch {
    // Rate limits throw from the action; every caller has a deterministic path.
    return { ok: false, error: "rate limited" };
  }
}
/**
 * Fixed-window rate limiting for Convex mutations and actions.
 *
 * Backed by the `rateBuckets` table: one row per (action, identifier).
 * The identifier is usually the user's Convex tokenIdentifier; for
 * unauthenticated paths (OTP request, public webhook) it can be an email
 * or IP-shaped string.
 *
 * Usage inside a mutation/action handler:
 *
 *   await consumeRateLimit(ctx, {
 *     action: "otp:send",
 *     identifier: email,
 *     limit: 5,
 *     windowMs: 60_000,
 *   });
 *
 * Throws `RateLimitError` when the limit is exceeded. Callers should catch
 * and return a 429-shaped message; the client surfaces the message verbatim.
 *
 * This is intentionally simple (no sliding window, no tiered limits) — the
 * goal is to stop abuse of expensive paths (OTP email, AI calls, hosted
 * voice), not to enforce precise quotas.
 *
 * Context handling: a MutationCtx has `db` directly; an ActionCtx only has
 * `runMutation`. We probe the shape and route through the internal mutation
 * from actions, inline through `ctx.db` from mutations.
 */

export class RateLimitError extends Error {
  constructor(
    message: string,
    public readonly retryAfterMs: number,
  ) {
    super(message);
    this.name = "RateLimitError";
  }
}

interface ConsumeArgs {
  action: string;
  identifier: string;
  limit: number;
  windowMs: number;
}

/**
 * Consume one unit from the rate-limit bucket. Throws `RateLimitError`
 * when the limit is exceeded within the current window.
 *
 * Works from both mutations (uses `ctx.db` inline) and actions (routes
 * through the `rateLimit.consume` internal mutation). The throw is
 * re-raised across the internal-mutation hop via the thrown error's
 * message.
 */
export async function consumeRateLimit(
  ctx: RateLimitCtx,
  { action, identifier, limit, windowMs }: ConsumeArgs,
): Promise<void> {
  // Mutation context: write directly.
  if (typeof (ctx as MutationCtx).db?.query === "function") {
    await consumeInline((ctx as MutationCtx).db, {
      action,
      identifier,
      limit,
      windowMs,
    });
    return;
  }
  // Action context: route through the internal mutation.
  if (typeof (ctx as ActionCtx).runMutation === "function") {
    // `internal` is lazily resolved so the module also loads in non-action
    // contexts (where `_generated/api` may not be resolvable).
    const { internal } = await import("../_generated/api");
    const result = await (ctx as ActionCtx).runMutation(
      internal.rateLimit.consume,
      { action, identifier, limit, windowMs },
    );
    if (result && typeof result === "object" && "error" in result) {
      throw new RateLimitError(
        (result as { error: string }).error,
        (result as { retryAfterMs: number }).retryAfterMs,
      );
    }
    return;
  }
  // Unknown context — fail open (don't block the handler).
  console.warn("[twyne:rateLimit] unknown ctx shape, skipping rate limit");
}

interface BucketDb {
  query: (table: "rateBuckets") => {
    withIndex: (
      name: "by_action_identifier",
      builder: (q: any) => any,
    ) => { unique: () => Promise<any> };
  };
  insert: (table: "rateBuckets", doc: any) => Promise<any>;
  patch: (id: any, patch: any) => Promise<void>;
}

type MutationCtx = { db: BucketDb };
type ActionCtx = { runMutation: (ref: any, args: any) => Promise<any> };
type RateLimitCtx = Partial<MutationCtx> & Partial<ActionCtx>;

/** Inline implementation — shared by the mutation path and the internal mutation. */
export async function consumeInline(
  db: BucketDb,
  { action, identifier, limit, windowMs }: ConsumeArgs,
): Promise<void> {
  const now = Date.now();
  const existing = await db
    .query("rateBuckets")
    .withIndex("by_action_identifier", (q: any) =>
      q.eq("action", action).eq("identifier", identifier),
    )
    .unique();

  if (!existing) {
    await db.insert("rateBuckets", {
      action,
      identifier,
      count: 1,
      windowStart: now,
    });
    return;
  }

  if (now - existing.windowStart >= windowMs) {
    await db.patch(existing._id, {
      count: 1,
      windowStart: now,
    });
    return;
  }

  if (existing.count >= limit) {
    const retryAfterMs = windowMs - (now - existing.windowStart);
    throw new RateLimitError(
      `Too many requests. Try again in ${Math.ceil(retryAfterMs / 1000)}s.`,
      retryAfterMs,
    );
  }

  await db.patch(existing._id, { count: existing.count + 1 });
}

