export type ExtractionFieldType =
  | "text"
  | "number"
  | "date"
  | "time"
  | "datetime"
  | "duration"
  | "list"
  | "estimate"
  | "forecast";

export type DurationUnit =
  | "seconds"
  | "minutes"
  | "hours"
  | "days"
  | "weeks"
  | "months"
  | "years";

export type ForecastInterval =
  | "step"
  | "minute"
  | "hour"
  | "day"
  | "week"
  | "month"
  | "quarter"
  | "year";

export interface ExtractionField {
  type: ExtractionFieldType;
  instructions?: string;
  unit?: string;
  integer?: boolean;
  decimals?: number;
  items?: "text" | "number" | "date";
  min?: number | string;
  max?: number | string;
  step?: number | "month" | "year";
  scale?: "linear" | "log";
  null_threshold?: number;
  horizon?: number;
  interval?: ForecastInterval;
}

export interface ExtractionRequest {
  state?: string;
  fields: Record<string, ExtractionField>;
  /** ISO date anchoring relative dates and dates written without a year. */
  reference_date?: string;
  options?: { include_quantiles?: boolean; return_state_text?: boolean };
}

export interface ExtractionAnswer {
  type: ExtractionFieldType;
  value: unknown;
  guess?: unknown;
  p_null?: number;
  confidence?: number;
  unit?: string;
  /** `text` answers: [start, end) into the state. */
  span?: [number, number];
  /** `list` answers: one span per item, in input order. */
  spans?: [number, number][];
  mean?: unknown;
  median?: unknown;
  p10?: unknown;
  p90?: unknown;
  p_below?: number;
  p_above?: number;
  quantiles?: unknown[];
  steps?: unknown[];
}

export interface ExtractionUsage {
  input_tokens: number;
  output_tokens: number;
  passes?: number;
}

export interface ExtractionResult {
  ok: boolean;
  model?: string;
  answers?: Record<string, ExtractionAnswer>;
  truncated?: boolean;
  usage?: ExtractionUsage;
  transport?: "notorganic" | "direct" | "none";
  error?: string;
  latencyMs?: number;
}

/** Input tokens only, at the published Workers AI rate. */
export const USD_PER_INPUT_TOKEN = 0.1 / 1_000_000;

/* ── Builders ──────────────────────────────────────────────────── */

export const text = (instructions?: string): ExtractionField => ({
  type: "text",
  ...(instructions ? { instructions } : {}),
});

export const list = (
  items: "text" | "number" | "date",
  instructions?: string,
): ExtractionField => ({
  type: "list",
  items,
  ...(instructions ? { instructions } : {}),
});

export function estimate(
  instructions: string,
  range: { min: number; max: number; unit?: string; step?: number; log?: boolean },
): ExtractionField {
  return {
    type: "estimate",
    instructions,
    min: range.min,
    max: range.max,
    ...(range.unit ? { unit: range.unit } : {}),
    ...(range.step ? { step: range.step } : {}),
    ...(range.log ? { scale: "log" as const } : {}),
  };
}

export function forecast(
  instructions: string,
  range: {
    min: number;
    max: number;
    horizon: number;
    interval: ForecastInterval;
    log?: boolean;
  },
): ExtractionField {
  return {
    type: "forecast",
    instructions,
    min: range.min,
    max: range.max,
    horizon: range.horizon,
    interval: range.interval,
    ...(range.log ? { scale: "log" as const } : {}),
  };
}

