import { describe, expect, test } from "bun:test";
import { generateKeyPairSync, verify, type KeyObject } from "node:crypto";

import {
  assertUniqueDidLink,
  createDpopKeyPair,
  createDpopProof,
  exchangeProductAssertion,
  notOrganicEnabled,
  notOrganicOpenAiRoute,
  issueNotOrganicAccessToken,
  signProductAssertion,
} from "../convex/lib/notorganic";

function decode(segment: string): Record<string, unknown> {
  return JSON.parse(Buffer.from(segment, "base64url").toString("utf8"));
}

describe("Not Organic product assertions", () => {
  const { privateKey, publicKey } = generateKeyPairSync("ed25519");
  const pem = privateKey.export({
    format: "pem",
    type: "pkcs8",
  }) as string;

  test("signs a verifiable 60-second Ed25519 assertion", async () => {
    const jwt = await signProductAssertion(
      {
        did: "did:plc:alice",
        feature: "persona-feedback",
        capabilities: ["infer:balanced"],
        sessionVersion: 7,
      },
      pem,
      {
        nowSeconds: 1_000,
        jti: "test-assertion",
        issuer: "https://api.notorganic.info",
        keyId: "twyne-test",
      },
    );
    const [header, payload, signature] = jwt.split(".");
    expect(decode(header!)).toEqual({
      alg: "EdDSA",
      typ: "JWT",
      kid: "twyne-test",
    });
    expect(decode(payload!)).toMatchObject({
      iss: "twyne",
      sub: "did:plc:alice",
      aud: "https://api.notorganic.info",
      iat: 1_000,
      exp: 1_060,
      session_version: 7,
      feature: "persona-feedback",
      capabilities: ["infer:balanced"],
    });
    expect(
      verify(
        null,
        Buffer.from(`${header}.${payload}`),
        publicKey as KeyObject,
        Buffer.from(signature!, "base64url"),
      ),
    ).toBe(true);
  });

  test("exchanges at the locked provider endpoint", async () => {
    let requestedUrl = "";
    const result = await exchangeProductAssertion("assertion", {
      fetch: (async (url, init) => {
        requestedUrl = String(url);
        expect(JSON.parse(String(init?.body))).toMatchObject({
          assertion: "assertion",
          dpop_jwk: { kty: "EC", crv: "P-256" },
        });
        return Response.json({
          access_token: "provider-token",
          expires_in: 300,
          token_type: "Bearer",
        });
      }) as typeof fetch,
    });
    expect(requestedUrl).toBe(
      "https://api.notorganic.info/v1/auth/token/exchange",
    );
    expect(result.accessToken).toBe("provider-token");
  });

  test("uses the configured token audience independently of the API issuer", async () => {
    await issueNotOrganicAccessToken(
      {
        did: "did:plc:alice",
        feature: "judgement",
        capabilities: ["judgement:evaluate"],
      },
      {
        NOTORGANIC_ENABLED: "true",
        NOTORGANIC_ASSERTION_PRIVATE_KEY: pem,
        NOTORGANIC_ISSUER: "https://api.notorganic.info",
        NOTORGANIC_AUDIENCE: "notorganic",
      },
      (async (url, init) => {
        expect(String(url)).toBe(
          "https://api.notorganic.info/v1/auth/token/exchange",
        );
        const payload = JSON.parse(String(init?.body));
        expect(decode(payload.assertion.split(".")[1]).aud).toBe("notorganic");
        return Response.json({ access_token: "provider-token" });
      }) as typeof fetch,
    );
  });

  test("routes hosted aliases with product and feature metadata", async () => {
    const route = notOrganicOpenAiRoute(
      {
        accessToken: "access-token",
        dpop: await createDpopKeyPair(),
      },
      "reasoning",
      "rubric-review",
      undefined,
      undefined,
      { maxCostMicrousd: 50_000 },
    );
    expect(route).toMatchObject({
      baseURL: "https://api.notorganic.info/v1",
      apiKey: "access-token",
      model: "reasoning",
      headers: {
        "x-notorganic-product": "twyne",
        "x-notorganic-feature": "rubric-review",
      },
    });
    expect(route.fetch).toBeFunction();
  });

  test("binds every request to the exchanged token with DPoP", async () => {
    const token = {
      accessToken: "access-token",
      dpop: await createDpopKeyPair(),
    };
    const proof = await createDpopProof(
      token,
      "https://api.notorganic.info/v1/responses",
      "POST",
      1_000,
    );
    const [header, payload, signature] = proof.split(".");
    expect(decode(header!)).toMatchObject({
      alg: "ES256",
      typ: "dpop+jwt",
      jwk: { kty: "EC", crv: "P-256" },
    });
    expect(decode(payload!)).toMatchObject({
      htm: "POST",
      htu: "https://api.notorganic.info/v1/responses",
      iat: 1_000,
      exp: 1_060,
    });
    const publicKey = await crypto.subtle.importKey(
      "jwk",
      token.dpop.publicJwk,
      { name: "ECDSA", namedCurve: "P-256" },
      false,
      ["verify"],
    );
    expect(
      await crypto.subtle.verify(
        { name: "ECDSA", hash: "SHA-256" },
        publicKey,
        Buffer.from(signature!, "base64url"),
        Buffer.from(`${header}.${payload}`),
      ),
    ).toBe(true);
  });
});

describe("provider identity boundary", () => {
  test("enforces one DID and one product subject", () => {
    expect(() =>
      assertUniqueDidLink(
        { did: "did:plc:a", productSubject: "subject-a" },
        { did: "did:plc:a", productSubject: "subject-b" },
        null,
      ),
    ).toThrow("already linked");
    expect(() =>
      assertUniqueDidLink(
        { did: "did:plc:a", productSubject: "subject-a" },
        null,
        { did: "did:plc:b", productSubject: "subject-a" },
      ),
    ).toThrow("already linked");
  });

  test("requires an explicit server feature flag", () => {
    expect(notOrganicEnabled({ NOTORGANIC_ENABLED: "true" })).toBe(true);
    expect(notOrganicEnabled({ NOTORGANIC_ENABLED: "0" })).toBe(false);
  });
});
/**
 * Internal mutation backing the rate limiter. Defined in a top-level Convex
 * file (not under `lib/`) so the Convex scanner picks it up and generates an
 * `internal.rateLimit.consume` reference. The logic lives in
 * `convex/lib/rateLimit.ts` so it can be shared with the inline mutation path.
 */
import { internalMutation } from "./_generated/server";
import { v } from "convex/values";
import { consumeInline, RateLimitError } from "./lib/rateLimit";

export const consume = internalMutation({
  args: {
    action: v.string(),
    identifier: v.string(),
    limit: v.number(),
    windowMs: v.number(),
  },
  handler: async (ctx, args) => {
    try {
      await consumeInline(ctx.db as any, args);
      return { ok: true as const };
    } catch (err) {
      if (err instanceof RateLimitError) {
        return {
          ok: false as const,
          error: err.message,
          retryAfterMs: err.retryAfterMs,
        };
      }
      // Unknown error — rethrow so the action sees it.
      throw err;
    }
  },
});
import { v } from "convex/values";
import {
  action,
  internalQuery,
  internalMutation,
  query,
} from "./_generated/server";
import {
  assertUniqueDidLink,
  issueNotOrganicAccessToken,
  notOrganicIssuer,
  providerJsonRequest,
} from "./lib/notorganic";

import { providerCheckoutSelection } from "./lib/providerCheckout";
import { summarizeHostedUsage } from "../src/utils/hosted-usage";

const didValidator = v.string();

function productSubject(identity: {
  subject?: string;
  tokenIdentifier: string;
}): string {
  return identity.subject || identity.tokenIdentifier;
}

export const getLinkedDidBySubject = internalQuery({
  args: { productSubject: v.string() },
  handler: async (ctx, { productSubject }) => {
    const link = await ctx.db
      .query("providerIdentities")
      .withIndex("by_productSubject", (q) =>
        q.eq("productSubject", productSubject),
      )
      .unique();
    return link?.verificationMethod === "notorganic_pkce" ? link : null;
  },
});

export const getMyProviderIdentity = query({
  args: {},
  handler: async (ctx) => {
    const identity = await ctx.auth.getUserIdentity();
    if (!identity) return null;
    const link = await ctx.db
      .query("providerIdentities")
      .withIndex("by_productSubject", (q) =>
        q.eq("productSubject", productSubject(identity)),
      )
      .unique();
    return link?.verificationMethod === "notorganic_pkce" ? link : null;
  },
});

export const saveVerifiedLink = internalMutation({
  args: { did: didValidator, subject: v.string(), sessionVersion: v.number() },
  handler: async (ctx, { did, subject, sessionVersion }) => {
    if (!/^did:[a-z0-9]+:[A-Za-z0-9._:%-]+$/.test(did)) {
      throw new Error("Invalid DID");
    }
    const [existingByDid, existingBySubject] = await Promise.all([
      ctx.db
        .query("providerIdentities")
        .withIndex("by_did", (q) => q.eq("did", did))
        .unique(),
      ctx.db
        .query("providerIdentities")
        .withIndex("by_productSubject", (q) => q.eq("productSubject", subject))
        .unique(),
    ]);
    assertUniqueDidLink(
      { did, productSubject: subject },
      existingByDid,
      existingBySubject,
    );
    const now = Date.now();
    if (existingBySubject) {
      await ctx.db.patch(existingBySubject._id, {
        verificationMethod: "notorganic_pkce",
        sessionVersion,
        verifiedAt: now,
        updatedAt: now,
      });
      return existingBySubject._id;
    }
    return await ctx.db.insert("providerIdentities", {
      did,
      productSubject: subject,
      verificationMethod: "notorganic_pkce",
      sessionVersion,
      verifiedAt: now,
      createdAt: now,
      updatedAt: now,
    });
  },
});

async function linkedDidForAction(ctx: any) {
  const identity = await ctx.auth.getUserIdentity();
  if (!identity) throw new Error("Not signed in");
  const row = await ctx.runQuery(
    // Kept dynamic until Convex regenerates api.d.ts for this new module.
    "providerIdentity:getLinkedDidBySubject" as any,
    { productSubject: productSubject(identity) },
  );
  if (!row) {
    throw new Error("Sign in with Not Organic to use your wallet.");
  }
  return row as { did: string; sessionVersion: number };
}

export const getWalletState = action({
  args: {},
  handler: async (ctx) => {
    const link = await linkedDidForAction(ctx);
    const token = await issueNotOrganicAccessToken({
      did: link.did,
      feature: "wallet",
      capabilities: ["wallet:read"],
      sessionVersion: link.sessionVersion,
    });
    return providerJsonRequest<unknown>(
      "/v1/wallet",
      token,
      {},
      {
        issuer: notOrganicIssuer(),
        feature: "wallet",
      },
    );
  },
});

/** Read-only, account-bound billing evidence. Never accept a DID from the browser. */
export const getHostedUsage = action({
  args: { from: v.union(v.number(), v.null()), to: v.number() },
  returns: v.object({
    billedMicrousd: v.number(),
    settledRequests: v.number(),
    unresolvedRequests: v.number(),
    unverifiedCostRequests: v.number(),
    unverifiedCostMicrousd: v.number(),
    truncated: v.boolean(),
  }),
  handler: async (ctx, range) => {
    if (
      !Number.isSafeInteger(range.to) ||
      range.to < 0 ||
      (range.from !== null &&
        (!Number.isSafeInteger(range.from) ||
          range.from < 0 ||
          range.from >= range.to))
    ) {
      throw new Error("Invalid hosted usage range");
    }
    const link = await linkedDidForAction(ctx);
    const token = await issueNotOrganicAccessToken({
      did: link.did,
      feature: "desk-usage",
      capabilities: ["usage:read"],
      sessionVersion: link.sessionVersion,
    });
    const payload = await providerJsonRequest<unknown>(
      "/v1/usage?limit=100",
      token,
      {},
      {
        issuer: notOrganicIssuer(),
        feature: "desk-usage",
      },
    );
    return summarizeHostedUsage(payload, range);
  },
});

export const createProviderCheckout = action({
  args: {
    planId: v.optional(v.string()),
    packId: v.optional(v.string()),
    successUrl: v.optional(v.string()),
  },
  handler: async (ctx, { planId, packId, successUrl }) => {
    const selection = providerCheckoutSelection(
      { planId, packId },
      {
        NOTORGANIC_ENABLED: process.env.NOTORGANIC_ENABLED,
        NOTORGANIC_TWYNE_PRO_V2_ENABLED:
          process.env.NOTORGANIC_TWYNE_PRO_V2_ENABLED,
      },
    );
    const link = await linkedDidForAction(ctx);
    const token = await issueNotOrganicAccessToken({
      did: link.did,
      feature: "billing-checkout",
      capabilities: ["billing:checkout"],
      sessionVersion: link.sessionVersion,
    });
    const returnUrl =
      successUrl ??
      `${(process.env.SITE_URL ?? "https://www.twyne.love").replace(/\/$/, "")}/pricing?checkout=success`;
    const expectedOrigin = new URL(
      process.env.SITE_URL ?? "https://www.twyne.love",
    ).origin;
    const parsedReturn = new URL(returnUrl);
    if (
      parsedReturn.protocol !== "https:" ||
      parsedReturn.origin !== expectedOrigin ||
      parsedReturn.username ||
      parsedReturn.password
    ) {
      throw new Error(
        "Provider checkout requires a same-site HTTPS success URL",
      );
    }
    const checkout = await providerJsonRequest<{ url: string }>(
      "/v1/billing/checkout",
      token,
      {
        method: "POST",
        body: JSON.stringify({
          ...selection,
          return_url: returnUrl,
        }),
      },
      {
        issuer: notOrganicIssuer(),
        feature: "billing-checkout",
      },
    );
    return { checkoutUrl: checkout.url };
  },
});

