describe("extraction", () => {
  test("forwards typed fields to Clairic and settles on reported input tokens", async () => {
    const { extract, requests, store, events } = fixture();
    const result = await extract({ state, fields, reference_date: "2026-10-20" });
    expect(requests[0]!.url).toBe("https://api.cloudflare.com/client/v4/accounts/acct/ai/run/@cf/cloudflare/clairic");
    expect(requests[0]!.headers.get("authorization")).toBe("Bearer cf-token");
    expect(requests[0]!.redirect).toBe("error");
    expect(await requests[0]!.json()).toEqual({ model: "clairic", state, fields, reference_date: "2026-10-20" });
    expect(result.model).toBe("extraction-clairic/clairic");
    expect(result.answers.po_number).toMatchObject({ value: null, guess: "INV-2291" });
    expect(result.usage).toEqual({ state_tokens: 30, input_tokens: 655, output_tokens: 0, passes: 3 });
    expect(store.settleWithResponse).toHaveBeenCalledTimes(1);
    expect((store.settleWithResponse.mock.calls[0]![0] as { actualCostMicrousd: number }).actualCostMicrousd).toBe(66);
    expect(events[0]).toMatchObject({ fields: 5, input_tokens: 655, usage_complete: true });
  });

  test("accepts unwrapped binding-style payloads", async () => {
    const { extract } = fixture({ model: "@cf/cloudflare/clairic", answers, truncated: true, usage: { input_tokens: 10, output_tokens: 0 } });
    const result = await extract({ state, fields });
    expect(result).toMatchObject({ model: "extraction-clairic/clairic", truncated: true });
  });

  for (const [label, body, code] of [
    ["no fields", { state, fields: {} }, "invalid_fields"],
    ["no state or images", { fields }, "invalid_state"],
    ["unknown type", { state, fields: { x: { type: "money" } } }, "invalid_field_type"],
    ["list without items", { state, fields: { x: { type: "list" } } }, "invalid_field"],
    ["estimate without range", { state, fields: { x: { type: "estimate" } } }, "invalid_field"],
    ["forecast without horizon", { state, fields: { x: { type: "forecast", min: 0, max: 1, interval: "day" } } }, "invalid_field"],
    ["bad duration unit", { state, fields: { x: { type: "duration", unit: "fortnights" } } }, "invalid_field"],
    ["unknown key", { state, fields: { x: { type: "text", criteria: [] } } }, "invalid_field"],
    ["bad name", { state, fields: { "1x": { type: "text" } } }, "invalid_field_name"],
    ["unknown top-level", { state, fields, questions: {} }, "invalid_body"],
  ] as const) {
    test(`rejects ${label} before reservation or upstream`, async () => {
      const { extract, requests, store } = fixture();
      await expect(extract(body)).rejects.toMatchObject({ status: 400, code });
      expect(store.reserve).not.toHaveBeenCalled();
      expect(requests).toHaveLength(0);
    });
  }

  test("releases on upstream rejection without forwarding upstream text", async () => {
    const { extract, store } = fixture({ errors: [{ message: state }] }, 429);
    await expect(extract({ state, fields })).rejects.toMatchObject({ status: 429, code: "extraction_rate_limited" });
    expect(store.release).toHaveBeenCalledTimes(1);
    expect(store.settleWithResponse).not.toHaveBeenCalled();
  });

  for (const [label, payload] of [
    ["missing field", { model: "clairic", truncated: false, answers: { ...answers, days_to_pay: undefined } }],
    ["wrong type", { model: "clairic", truncated: false, answers: { ...answers, due_date: { type: "text", value: "x" } } }],
    ["span past state", { model: "clairic", truncated: false, answers: { ...answers, invoice_number: { type: "text", span: [0, 9999], value: "x" } } }],
    ["foreign model", { model: "glm-5.3", truncated: false, answers }],
  ] as const) {
    test(`reconciles at the ceiling on invalid answers: ${label}`, async () => {
      const { extract, store } = fixture(JSON.parse(JSON.stringify(payload)));
      await expect(extract({ state, fields })).rejects.toMatchObject({ status: 502, code: "extraction_invalid_response" });
      expect(store.reconcile).toHaveBeenCalledTimes(1);
    });
  }

  test("reconciles when usage is missing", async () => {
    const { extract, store } = fixture({ model: "clairic", answers, truncated: false });
    const result = await extract({ state, fields });
    expect(result.usage).toBeNull();
    expect(store.reconcile).toHaveBeenCalledTimes(1);
    expect(store.settleWithResponse).not.toHaveBeenCalled();
  });

  test("reservation grows with passes that re-read a long state", () => {
    const small = validateExtractionRequest({ state: "x".repeat(400), fields });
    const wide = validateExtractionRequest({ state: "x".repeat(30_000), fields: Object.fromEntries(Array.from({ length: 64 }, (_, i) => [`f${i}`, { type: "text", instructions: "y".repeat(400) }])) });
    expect(extractionMaxInputTokens(small)).toBeLessThan(2_000);
    expect(extractionMaxInputTokens(wide)).toBeGreaterThan(30_000);
  });

  test("config is off without a token and fails closed without an account", () => {
    expect(extractionConfigFromEnv({})).toBeUndefined();
    expect(() => extractionConfigFromEnv({ CLOUDFLARE_AI_API_TOKEN: "t" })).toThrow();
    expect(extractionConfigFromEnv({ CLOUDFLARE_AI_API_TOKEN: "t", CLOUDFLARE_ACCOUNT_ID: "a" })?.price).toEqual({ unit: "input_token", microusd: 0.1 });
  });
});

