 1	/**
 2	 * One door for every Clairic extraction Twyne asks for, as `judgement-client`
 3	 * is for Jev. Always through the Convex action: the provider credential lives
 4	 * on the server, and Not Organic meters the spend.
 5	 */
 6	import type { ConvexClient } from "convex/browser";
 7	import { api } from "../../convex/_generated/api";
 8	import type { ExtractionRequest, ExtractionResult } from "./extraction";
 9	
10	export async function askExtraction(
11	  client: ConvexClient | null | undefined,
12	  request: ExtractionRequest,
13	): Promise<ExtractionResult> {
14	  if (!client) return { ok: false, transport: "none", error: "signed out" };
15	  const started = performance.now();
16	  try {
17	    const result = (await client.action(
18	      api.extraction.extract,
19	      request,
20	    )) as ExtractionResult;
21	    return { ...result, latencyMs: Math.round(performance.now() - started) };
22	  } catch {
23	    // Rate limits throw from the action; every caller has a deterministic path.
24	    return { ok: false, error: "rate limited" };
25	  }
26	}

